class SummaryRanges(object):
    def __init__(self):
        self.flags = [0 for _ in range(10001)]

    def addNum(self, val):
        """
        :type val: int
        :rtype: None
        """
        self.flags[val] = 1

    def getIntervals(self):
        """
        :rtype: List[List[int]]
        """
        ans = []
        cur_start, cur_end = -1, -1
        for i in range(10001):
            if self.flags[i] == 1:
                if cur_start == -1:
                    cur_start = i
                    cur_end = i
                else:
                    cur_end = i
            else:
                if cur_start != -1:
                    ans.append([cur_start, cur_end])
                    cur_start = -1
                    cur_end = -1
        if cur_start != -1:
            ans.append([cur_start, cur_end])
        return ans


